@dataclass(frozen=True)
class MediaCachePruneResult:
    directory: str
    scanned_files: int
    removed_files: int
    removed_bytes: int
    truncated: bool


def _empty_result(directory: object) -> MediaCachePruneResult:
    return MediaCachePruneResult(
        directory=str(directory),
        scanned_files=0,
        removed_files=0,
        removed_bytes=0,
        truncated=False,
    )


def _unlink(path: Path) -> Optional[int]:
    """Remove one file, returning the bytes freed, or None when it could not be removed."""

    try:
        size = path.lstat().st_size
    except FileNotFoundError:
        return 0
    except OSError as exc:
        logger.warning("Failed to stat media cache entry %s: %s", path, exc)
        return None

    try:
        path.unlink()
    except FileNotFoundError:
        return 0
    except OSError as exc:
        logger.warning("Failed to remove media cache entry %s: %s", path, exc)
        return None

    return size


def prune_media_cache_dir(
    directory: str | Path,
    *,
    max_bytes: int,
    max_age_seconds: int,
    max_removals: int,
) -> MediaCachePruneResult:
    """Reap oldest-first from one media cache directory until it is inside budget.

    Media entries are keyed by ProjectFile id or by a content cache key, so a
    re-upload orphans the previous generation instead of overwriting it: this is
    a space problem, not a freshness problem, and the sweep only ever removes
    direct children that are plain files. Symlinks and subdirectories are left
    alone so a tampered cache root cannot turn a budget sweep into a recursive
    delete somewhere else on the volume.
    """

    max_removals = max(0, int(max_removals))

    try:
        root = Path(directory).resolve()
    except OSError as exc:
        logger.warning("Failed to resolve media cache directory %s: %s", directory, exc)
        return _empty_result(directory)

    try:
        if not root.is_dir():
            return _empty_result(root)
        children = list(root.iterdir())
    except OSError as exc:
        logger.warning("Failed to list media cache directory %s: %s", root, exc)
        return _empty_result(root)

    entries: list[tuple[Path, int, float]] = []
    total_bytes = 0
    for child in children:
        try:
            info = child.lstat()
            if not stat.S_ISREG(info.st_mode):
                continue
            if child.resolve().parent != root:
                logger.warning("Skipping media cache entry outside %s: %s", root, child)
                continue
        except OSError:
            continue
        entries.append((child, info.st_size, info.st_mtime))
        total_bytes += info.st_size

    sizes_by_name = {path.name: size for path, size, _ in entries}
    entries.sort(key=lambda entry: entry[2])

    now = time.time()
    removed_files = 0
    removed_bytes = 0
    used_slots = 0
    truncated = False

    for path, size, mtime in entries:
        if path.name.endswith(_MIME_SIDECAR_SUFFIX):
            # Removed together with its image below; reaped on its own only when orphaned.
            if path.name[: -len(_MIME_SIDECAR_SUFFIX)] in sizes_by_name:
                continue

        # Entries are oldest first, so once one is young enough and the directory
        # fits the budget, everything after it is too.
        if (now - mtime) <= max_age_seconds and total_bytes <= max_bytes:
            break

        if used_slots >= max_removals:
            truncated = True
            break

        freed = _unlink(path)
        if freed is None:
            continue

        # One image plus its mime sidecar is a single logical removal, so the
        # sidecar never consumes a second slot; its bytes still count as freed.
        used_slots += 1
        removed_files += 1
        removed_bytes += freed
        total_bytes -= size

        sidecar_size = sizes_by_name.get(f"{path.name}{_MIME_SIDECAR_SUFFIX}")
        if sidecar_size is None:
            continue
        sidecar_freed = _unlink(root / f"{path.name}{_MIME_SIDECAR_SUFFIX}")
        if sidecar_freed is None:
            continue
        removed_files += 1
        removed_bytes += sidecar_freed
        total_bytes -= sidecar_size

    return MediaCachePruneResult(
        directory=str(root),
        scanned_files=len(entries),
        removed_files=removed_files,
        removed_bytes=removed_bytes,
        truncated=truncated,
    )


def prune_media_caches() -> list[MediaCachePruneResult]:
    """Sweep the image, video and video-frame caches. Each gets its own budget."""

    max_bytes = int(settings.media_cache_max_bytes)
    max_age_seconds = int(settings.media_cache_max_age_hours) * 3600
    max_removals = int(settings.media_cache_prune_max_removals)

    directories = (
        settings.image_cache_dir,
        settings.video_cache_dir,
        settings.video_frame_cache_dir,
    )

    results: list[MediaCachePruneResult] = []
    for directory in directories:
        try:
            result = prune_media_cache_dir(
                directory,
                max_bytes=max_bytes,
                max_age_seconds=max_age_seconds,
                max_removals=max_removals,
            )
        except Exception:
            logger.warning("Media cache prune failed for %s", directory, exc_info=True)
            continue
        if result.truncated:
            # An incomplete sweep must be visible: otherwise a directory that is
            # still over budget looks identical to one that fits.
            logger.warning(
                "Media cache prune hit the %s-removal cap for %s and left it over budget",
                max_removals,
                result.directory,
            )
        results.append(result)

    return results

"""Bounded, event-loop-local operations. No distributed coordination or cache.

The caller that supplies a factory owns its resources until settlement. If it
is cancelled, its request stays suspended here until the factory settles, so
FastAPI cannot close its DB dependency underneath the shared operation. Other
callers may leave immediately. A synchronous worker must use settled_thread:
Python threads cannot be preempted, and their slot stays occupied until done.
"""

import asyncio
from collections.abc import Awaitable, Callable, Hashable
from dataclasses import dataclass, field
from typing import TypeVar
from weakref import WeakKeyDictionary

import anyio

T = TypeVar("T")


class SingleFlightBusy(RuntimeError):
    pass


class SingleFlightTimeout(RuntimeError):
    pass


async def _drain(task: asyncio.Task) -> None:
    """Wait through repeated caller cancellation; consume orphan exceptions."""
    with anyio.CancelScope(shield=True):
        while not task.done():
            try:
                await asyncio.shield(task)
            except asyncio.CancelledError:
                continue
            except Exception:
                break
    if not task.cancelled():
        task.exception()


async def settled_thread(operation: Callable[[], T]) -> T:
    task = asyncio.create_task(anyio.to_thread.run_sync(operation))
    try:
        return await asyncio.shield(task)
    except asyncio.CancelledError:
        await _drain(task)
        raise


@dataclass
class _Entry:
    task: asyncio.Task | None = None
    consumers: int = 0
    accepting: bool = True


@dataclass
class _State:
    slots: asyncio.Semaphore
    entries: dict[Hashable, _Entry] = field(default_factory=dict)
    consumers: int = 0
    running: int = 0


class SingleFlight:
    def __init__(self, *, max_running=4, max_queued=32, max_consumers=256, timeout=120.0):
        if max_running < 1 or max_queued < 0 or max_consumers < 1 or timeout <= 0:
            raise ValueError("Invalid singleflight budget")
        self.max_running = max_running
        self.max_queued = max_queued
        self.max_consumers = max_consumers
        self.timeout = timeout
        self._states: WeakKeyDictionary = WeakKeyDictionary()

    def stats(self) -> dict[str, int]:
        state = self._states.get(asyncio.get_running_loop())
        return {"entries": len(state.entries) if state else 0,
                "running": state.running if state else 0,
    if cached is not None:
        return Response(
            content=cached.content,
            media_type=cached.mime_type,
            headers={**response_headers, "X-Image-Cache": cached.cache_status},
        )

    drive_client = await build_isolated_drive_client(db)
    if not drive_client:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail="No se pudo configurar Google Drive para servir la imagen"
        )
    try:
        loaded = await load_project_image(image_ref, drive_client)
    except Exception as exc:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail="No se pudo descargar la imagen desde Google Drive"
        ) from exc

    return Response(
        content=loaded.content,
        media_type=loaded.mime_type,
        headers={**response_headers, "X-Image-Cache": loaded.cache_status},
    )


async def _compute_video_frame_time_s(
    db: AsyncSession,
    project_id: UUID,
    participant_code: Optional[str],
    scenario: Optional[str],
    absolute_time_s: float,
) -> float:
    if not participant_code or is_all_scenarios(scenario):
        return max(0.0, absolute_time_s)

    try:
        reader = ParquetReaderService(db)
        # Resolved once and passed to both reads: a re-ingestion landing between
        # them would otherwise have the miss fall back onto a different generation
        # than the lookup that missed.
        generation = await reader.resolve_cache_generation(project_id)
        cacheable = observe_project_generation(project_id, generation)
        hit, onset_s = get_cached_preview_onset(
            project_id, generation, participant_code, str(scenario)
        )
        if not hit:
            df = await reader.read_from_cache_only(
                project_id,
                participant_code,
                generation,
                projection=_VIDEO_PREVIEW_TIMING_PROJECTION,
            )
            if df is None:
                df = await reader.read(
                    project_id,
                    participant_code,
                    generation,
                    projection=_VIDEO_PREVIEW_TIMING_PROJECTION,
                )
            onset_s = await settled_thread(
                lambda: compute_preview_scenario_onset_s(df, scenario)
            )
            if cacheable:
                cache_preview_onset(
                    project_id,
                    generation,
                    participant_code,
                    str(scenario),
                    onset_s,
                )
        if onset_s is not None:
            return round(max(0.0, float(absolute_time_s) - onset_s), 4)
    except Exception as exc:
        logger.warning(
            "Falling back to absolute video preview time for project_id=%s scenario=%r: %s",
            project_id,
            scenario,
            exc,
        )

    return max(0.0, absolute_time_s)


async def _ensure_video_source_cached(
    project_file: ProjectFile,
    db: AsyncSession,
    cache_key: str,
) -> Path:
    video_path = _video_source_cache_path(project_file, cache_key)
    try:
        if video_path.exists() and video_path.stat().st_size > 0:
            return video_path
    except OSError:
        pass

    drive_client = await build_isolated_drive_client(db)
    if not drive_client:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail="No se pudo configurar Google Drive para servir el video"
        )

    try:
        await settled_thread(
            lambda: drive_client.download_file_to_path(
                project_file.external_id,
                str(video_path),
            )
        )
    except Exception as exc:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail="No se pudo descargar el video desde Google Drive"
        ) from exc

    return video_path


def _probe_video_duration_s(video_path: Path) -> Optional[float]:
    try:
        result = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-show_entries",
                "format=duration",
                "-of",
                "default=noprint_wrappers=1:nokey=1",
                str(video_path),
            ],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired):
        return None

    if result.returncode != 0:
        return None

    try:
        duration = float(result.stdout.strip())
    except (TypeError, ValueError):
        return None

    if duration <= 0:
        return None
    return duration


def _run_ffmpeg_frame_extract(video_path: Path, frame_path: Path, time_s: float) -> None:
    temp_frame_path = frame_path.with_name(f"{frame_path.stem}.tmp{frame_path.suffix}")
    try:
        temp_frame_path.unlink(missing_ok=True)
    except OSError:
        pass

    try:
        result = subprocess.run(
            [
                "ffmpeg",
                "-hide_banner",
                "-loglevel",
                "error",
                "-ss",
                f"{time_s:.3f}",
                "-i",
                str(video_path),
                "-frames:v",
                "1",
                "-vf",
                "scale='min(1920,iw)':-2",
                "-q:v",
                "3",
                "-y",
                str(temp_frame_path),
            ],
            capture_output=True,
            text=True,
            timeout=_FFMPEG_TIMEOUT_SECONDS,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("FFmpeg is not installed in the backend container") from exc
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("FFmpeg timed out while generating the video frame") from exc

    if result.returncode != 0:
        message = result.stderr.strip() or "FFmpeg failed without stderr output"
        raise RuntimeError(message)

    if not temp_frame_path.exists() or temp_frame_path.stat().st_size == 0:
        raise RuntimeError("FFmpeg did not produce a video frame")

    temp_frame_path.replace(frame_path)


def _extract_video_frame(
    video_path: Path,
    frame_path: Path,
    frame_time_s: float,
    video_identity: str,
) -> None:
    duration_s = get_video_duration_s(
        video_identity, video_path, _probe_video_duration_s
    )
    safe_time_s = max(0.0, frame_time_s)
    if duration_s is not None:
        safe_time_s = min(safe_time_s, max(0.0, duration_s - 0.05))

    try:
        _run_ffmpeg_frame_extract(video_path, frame_path, safe_time_s)
    except RuntimeError:
        if safe_time_s <= 0:
            raise
        _run_ffmpeg_frame_extract(video_path, frame_path, 0.0)

@router.get("/{project_id}/files/{file_id}/preview")
async def get_project_file_preview(
    project_id: UUID,
    file_id: UUID,
    request: Request,
    time_s: float = Query(default=0.0, ge=0.0, le=86400.0),
    scenario: Optional[str] = Query(default=None),
    participant_code: Optional[str] = Query(default=None),
    current_user: str = Depends(get_current_user),
    db: AsyncSession = Depends(get_db)
):
    """Serve an image preview for image files or a time-specific frame for videos."""
    project_file = await _load_project_file(project_id, file_id, current_user, db)

    if _is_image_file(project_file):
        return await _serve_project_file_image(project_file, request, db)

    if not _is_video_file(project_file):
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Requested file is neither an image nor a video"
        )

    if not project_file.external_id:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="File storage reference not found"
        )

    cache_key = _project_file_cache_key(project_file)
    relative_time_s = await _compute_video_frame_time_s(
        db,
        project_id,
        participant_code,
        scenario,
        time_s,
    )
    frame_time_s = round(max(0.0, relative_time_s), _VIDEO_FRAME_TIME_DECIMALS)
    frame_path = _video_frame_cache_path(cache_key, frame_time_s)
    frame_cache_key = f"{cache_key}:frame:{frame_time_s:.{_VIDEO_FRAME_TIME_DECIMALS}f}"
    etag = _build_image_etag(frame_cache_key)
    response_headers = {
        "Cache-Control": "private, max-age=300, stale-while-revalidate=60",
        "ETag": etag,
    }

    frame_exists = await settled_thread(lambda: _video_frame_cache_exists(frame_path))
    if frame_exists:
        if request.headers.get("if-none-match") == etag:
            return Response(status_code=status.HTTP_304_NOT_MODIFIED, headers=response_headers)
        cached_frame = await settled_thread(lambda: _read_video_frame_cache(frame_path))
        if cached_frame is not None:
            return Response(
                content=cached_frame,
                media_type=_VIDEO_FRAME_MIME_TYPE,
                headers={
                    **response_headers,
                    "X-Video-Frame-Cache": "DISK",
                    "X-Video-Frame-Time": f"{frame_time_s:.{_VIDEO_FRAME_TIME_DECIMALS}f}",
                },
            )

    preview_lock = await _get_video_preview_lock(cache_key)
    try:
        async with preview_lock:
            exists_after_lock = await settled_thread(
                lambda: _video_frame_cache_exists(frame_path)
            )
            if exists_after_lock:
                if request.headers.get("if-none-match") == etag:
                    return Response(status_code=status.HTTP_304_NOT_MODIFIED, headers=response_headers)
                cached_after_lock = await settled_thread(
                    lambda: _read_video_frame_cache(frame_path)
                )
                if cached_after_lock is not None:
                    return Response(
                        content=cached_after_lock,
                        media_type=_VIDEO_FRAME_MIME_TYPE,
                        headers={
                            **response_headers,
                            "X-Video-Frame-Cache": "DISK",
                            "X-Video-Frame-Time": f"{frame_time_s:.{_VIDEO_FRAME_TIME_DECIMALS}f}",
                        },
                    )

            video_path = await _ensure_video_source_cached(project_file, db, cache_key)
            try:
                await settled_thread(
                    lambda: _extract_video_frame(
                        video_path,
                        frame_path,
                        frame_time_s,
                        cache_key,
                    )
